import org.joget.workflow.model.WorkflowAssignment;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.sql.ResultSet;
 String currentDate = "#date.dd/MM/yyyy#";


String etab ="#requestParam.etab#";
String formation ="#requestParam.formation#";
String niveau ="#requestParam.niveau#";
 String c_adresse_electronique_directeur ="";
 String nom_etablissement ="#form.etablissement.etablissement[{requestParam.etab}]#";
 String id_etudiant ="#form.inscription_etud.id_etudiant[{currentUser.email}]#";







try {
 
 
 Connection con = null;
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();


 String selectQuery="SELECT c_adresse_electronique_directeur FROM jwdb.app_fd_directeurs where c_nom_etablissement = ? ;";



 PreparedStatement stmt = con.prepareStatement(selectQuery);
 stmt.setString(1, etab);
 ResultSet rs = stmt.executeQuery();

 


StringBuilder allAddresses = new StringBuilder(); // Use StringBuilder to store concatenated values.

while (rs.next()) {
 String c_adresse_electronique_directeur = rs.getString("c_adresse_electronique_directeur");

 if (allAddresses.length() > 0) {
 allAddresses.append(";"); // Add semicolon only after the first value.
 }

 allAddresses.append(c_adresse_electronique_directeur);
}

String concatenatedAddresses = allAddresses.toString();

if (concatenatedAddresses.isEmpty()) {
 WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(), "nom_directeur", "user_to_backup_processes");
} else {
 // If addresses were found, set the workflow variable as before
 WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");
 wm.activityVariable(workflowAssignment.getActivityId(), "nom_directeur", concatenatedAddresses);
}


 rs.close();
 stmt.close();
 
 

 con.close();
} catch (SQLException e) {
 LogUtil.error("CaseVioo", e, "Error executing SQL query");
} catch (Exception ex) {
 LogUtil.error("CaseVioo", ex, "Error in script Generation fiche cv post CaseVioo Ouverture");
}


AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");

// Get record ID from the workflow
String recordid = appService.getOriginProcessId(workflowAssignment.getProcessId());
 String c_discipline = null;
 String c_domaine = null;
 String c_specialite = null;
 String id_domaine = null;
 String id_spe = null;
Connection con = null;

try {
 // Initialize necessary variables


 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();

 if (!con.isClosed()) {

 // First query: get c_discipline, c_domaine, and c_specialite
 PreparedStatement stmt1 = con.prepareStatement("SELECT c_discipline, c_domaine, c_specialite FROM jwdb.app_fd_formations WHERE id LIKE ?;");
 stmt1.setString(1, formation); // Assuming 'id' is already set
 ResultSet rs = stmt1.executeQuery();

 if (rs.next()) {
 c_discipline = rs.getString("c_discipline");
 id_domaine = rs.getString("c_domaine");
 id_spe = rs.getString("c_specialite");
 }

 // Close the first statement and result set
 rs.close();
 stmt1.close();

 // Second query: retrieve discipline from app_fd_discipline using the value from the first query
 PreparedStatement stmt2 = con.prepareStatement("SELECT c_discipline FROM jwdb.app_fd_discipline WHERE id LIKE ?;");
 stmt2.setString(1, c_discipline); // Using the same id for discipline
 rs = stmt2.executeQuery();

 if (rs.next()) {
 c_discipline = rs.getString("c_discipline");
 }

 // Close the second statement and result set
 rs.close();
 stmt2.close();

 // Third query: retrieve domaine using the c_domaine value from the first query
 PreparedStatement stmt3 = con.prepareStatement("SELECT c_domaine FROM jwdb.app_fd_domaine WHERE c_uuid LIKE ?;");
 stmt3.setString(1, id_domaine); // Using the retrieved id_domaine from the first query
 rs = stmt3.executeQuery();

 if (rs.next()) {
 c_domaine = rs.getString("c_domaine");
 }

 // Close the third statement and result set
 rs.close();
 stmt3.close();

 // Fourth query: retrieve specialite using the c_specialite value from the first query
 PreparedStatement stmt4 = con.prepareStatement("SELECT c_specialite FROM jwdb.app_fd_specialite WHERE id LIKE ?;");
 stmt4.setString(1, id_spe); // Using the retrieved id_spe from the first query
 rs = stmt4.executeQuery();

 if (rs.next()) {
 c_specialite = rs.getString("c_specialite");
 }

 // Close the fourth statement and result set
 rs.close();
 stmt4.close();
 }
} catch (Exception e) {
 LogUtil.error("Sample app - Form 1", e, "Error loading user data in load binder");
} finally {
 try {
 if (con != null) {
 con.close();
 }
 } catch (Exception ex) {
 LogUtil.error("Script P¨V commission", ex, "Script P¨V commission");
 }
}



Connection con = null;
PreparedStatement stmtInsert = null;
String historique = "[{\"modifiedBy\":\"#currentUser.username#\",\"dateModified\":\"#date.dd/MM/yyyy#\",\"statut\":\"En cours\"}]";

try {
 // Get data source connection
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();

 // Prepare SQL insert statement
 String insertSql = "INSERT INTO app_fd_inscription_ecole " +
 "(id, c_cycle, c_domaine, c_etablissement, createdBy, c_activityprocessid, c_statut,c_mail_directeur,c_specialite,c_formation,c_id_etablissement,c_niveau,c_historique,c_email_etudiant,c_id_etudiant) " +
 "VALUES (?, ?, ?, ?, ?, ?, ?, ?,?,?,?,?,?,?,?)";
 
 stmtInsert = con.prepareStatement(insertSql);
 stmtInsert.setString(1, recordid);
 stmtInsert.setString(2, c_discipline);
 stmtInsert.setString(3, c_domaine);
 stmtInsert.setString(4, nom_etablissement);
 stmtInsert.setString(5,"#currentUser.username#");
 stmtInsert.setString(6,"#assignment.processId#");
 stmtInsert.setString(7, "En cours"); // Set status to "En cours"
 stmtInsert.setString(8, c_adresse_electronique_directeur); // Set status to "En cours"
 stmtInsert.setString(9, c_specialite); // Set status to "En cours"
 stmtInsert.setString(10, formation); // Set status to "En cours"
 stmtInsert.setString(11, etab); // Set status to "En cours"
 stmtInsert.setString(12, niveau); // Set status to "En cours"
 stmtInsert.setString(13, historique); // Set status to "En cours"
 stmtInsert.setString(14, "#currentUser.email#"); // Set status to "En cours"
 stmtInsert.setString(15, id_etudiant); // Set status to "En cours"
 

 
 // Execute insert
 stmtInsert.executeUpdate();

} catch (SQLException e) {
 LogUtil.error("YourClassName", e, "Error inserting data into app_fd_inscription_ecole");
} finally {
 // Close statement and connection
 if (stmtInsert != null) {
 try {
 stmtInsert.close();
 } catch (SQLException e) {
 LogUtil.error("YourClassName", e, "Error closing PreparedStatement");
 }
 }
 if (con != null) {
 try {
 con.close();
 } catch (SQLException e) {
 LogUtil.error("YourClassName", e, "Error closing Connection");
 }
 }
}






