","jdbcDatasource":"default"}},{"className":"org.joget.apps.app.lib.EmailTool","properties":{"cc":"","toSpecific":"#form.inscription_ecole.email_etudiant#","bcc":"","icsAttachement":"","subject":"Votre demande d'inscription a été refusée","retryCount":"","formDefId":"","toParticipantId":"","message":"<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Demande d'inscription - Candidature refusée</title>
</head>
<body>
    <p>Bonjour <strong>#form.inscription_ecole.createdByName#</strong>,</p>

    <p>Après étude de votre demande d'inscription à la formation <strong>#form.formations.formation[{form.inscription_ecole.formation}]#</strong>, nous regrettons de vous informer que votre candidature n'a pas été retenue.</p>

    <p>Nous vous remercions de l'intérêt que vous portez à notre établissement et restons disponibles pour toute question ou éclaircissement concernant cette décision.</p>

    <p>Nous vous souhaitons le meilleur dans la poursuite de vos projets académiques.</p>

    <p>Cordialement,<br>
        <strong>#form.inscription_ecole.etablissement#</strong>,<br>
        Service des admissions
    </p>
</body>
</html>","p12":"","security":"","password":"","storepass":"","port":"","isHtml":"true","host":"","alias":"","files":[],"from":"","retryInterval":"","fields":[],"username":""}},{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import org.json.JSONArray;
import org.json.JSONObject;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;

String modifiedBy = "#form.app_fd_inscription_ecole.modifiedBy#";
String dateModified = "#form.app_fd_inscription_ecole.date_action#";
String statut = "#form.app_fd_inscription_ecole.statut#";
String id = "#form.app_fd_inscription_ecole.id#";

DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
Connection con = null;
PreparedStatement stmtSelect = null;
PreparedStatement stmtInsert = null;
ResultSet rs = null;
String selectSQL = "SELECT c_historique FROM app_fd_inscription_ecole WHERE id = ?";
String updateSQL = "UPDATE app_fd_inscription_ecole SET c_historique = ? WHERE id = ?";

try {
    // Create a JSON object with statut, modifiedBy, and dateModified
    JSONObject newJsonObject = new JSONObject();
    newJsonObject.put("statut", statut);
    newJsonObject.put("modifiedBy", modifiedBy);
    newJsonObject.put("dateModified", dateModified);

    con = ds.getConnection();
    
    if (!con.isClosed()) {
        // First, retrieve the existing c_historique
        stmtSelect = con.prepareStatement(selectSQL);
        stmtSelect.setString(1, id);  // Set the id for the WHERE clause
        rs = stmtSelect.executeQuery();
        
        JSONArray jsonArray;
        
        if (rs.next()) {
            String existingHistorique = rs.getString("c_historique");
            
            // Check if c_historique exists and is not null or empty
            if (existingHistorique != null && !existingHistorique.isEmpty()) {
                // Parse the existing c_historique into a JSON array
                jsonArray = new JSONArray(existingHistorique);
            } else {
                // If no existing historique, initialize a new array
                jsonArray = new JSONArray();
            }
        } else {
            // If no record is found for the id, initialize a new array
            jsonArray = new JSONArray();
        }

        // Add the new JSON object to the array
        jsonArray.put(newJsonObject);

        // Prepare the update statement
        stmtInsert = con.prepareStatement(updateSQL);
        stmtInsert.setString(1, jsonArray.toString());  // Set the updated JSON array
        stmtInsert.setString(2, id);  // Set the id for the WHERE clause
        
        int rowsUpdated = stmtInsert.executeUpdate();
        
        if (rowsUpdated > 0) {
            LogUtil.info("DAO", "c_historique column updated successfully with appended JSON array for id: " + id);
        }
    }
} catch (SQLException e) {
    LogUtil.error("error update DAO", e, e.getMessage());
} finally {
    try {
        if (rs != null) {
            rs.close();
        }
        if (stmtSelect != null) {
            stmtSelect.close();
        }
        if (stmtInsert != null) {
            stmtInsert.close();
        }
        if (con != null) {
            con.close();
        }
    } catch (Exception ex) {
        LogUtil.error("DAO", ex, ex.getMessage());
    }
}
"}}]}

{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"//kill processes
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import org.joget.apps.app.service.AppUtil;
import org.joget.workflow.model.service.WorkflowManager;
import org.joget.commons.util.LogUtil;
String currentuser = "#form.inscription_ecole.email_etudiant#";
String id_instance = "#form.inscription_ecole.id#";

WorkflowManager workflowManager = (WorkflowManager) AppUtil.getApplicationContext().getBean("workflowManager");
Connection con = null;

try {
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();

 if (!con.isClosed()) {
 String selectSQL = "SELECT DISTINCT e.id, shk.ActivityProcessDefName, shk.ActivityProcessId, shk.ActivityId, e.c_formation,e.c_id_etablissement,e.modifiedBy, e.c_mail_directeur,e.c_statut " +
 "FROM jwdb.SHKAssignmentsTable AS shk " +
 "JOIN jwdb.app_fd_inscription_ecole AS e ON shk.ActivityProcessId = e.c_activityprocessid " +
 "WHERE e.createdBy = ? AND e.id != ?;";

 PreparedStatement stmtSelectFolders = con.prepareStatement(selectSQL);
 stmtSelectFolders.setString(1, currentuser);
 stmtSelectFolders.setString(2, id_instance);

 ResultSet rs = stmtSelectFolders.executeQuery();

 while (rs.next()) {
 String c_activityprocessid = rs.getString("ActivityProcessId");
 String c_processDefId = rs.getString("ActivityProcessDefName");
 String c_activityId = rs.getString("ActivityId");
 String c_mail_directeur = rs.getString("c_mail_directeur");
 String modifiedBy = rs.getString("modifiedBy");
 String id = rs.getString("id");
 String id_etablissement = rs.getString("c_id_etablissement");
 String formation = rs.getString("c_formation");
 String statut = rs.getString("c_statut");

 LogUtil.info("Process Info", "c_activityprocessid: " + c_activityprocessid + ", c_processDefId: " + c_processDefId + ", c_activityId: " + c_activityId);

 String update_field = "UPDATE app_fd_inscription_ecole SET c_steps = '2', c_statut = 'Annulé' WHERE id = ?;";
 PreparedStatement update_sql = con.prepareStatement(update_field);
 update_sql.setString(1, id);
 update_sql.executeUpdate();
if(statut.equals("Accepté")) {



String update_field = "UPDATE app_fd_quotas SET c_quota = c_quota + 1 WHERE id = CONCAT(?, ';', ?) and c_quota_check ='oui';";
PreparedStatement update_sql = con.prepareStatement(update_field);
update_sql.setString(1, formation); // First parameter
update_sql.setString(2, id_etablissement); // Second parameter
update_sql.executeUpdate();
}







 if (modifiedBy.equals(currentuser)) {
 workflowManager.activityVariable(c_activityId, "decision", "Annuler");
 workflowManager.assignmentForceComplete(c_processDefId, c_activityprocessid, c_activityId, c_mail_directeur);
 } else {
 workflowManager.activityVariable(c_activityId, "decision", "Annuler");
 workflowManager.assignmentForceComplete(c_processDefId, c_activityprocessid, c_activityId, currentuser);
 }
 }
 }
} catch (Exception e) {
 LogUtil.error("assignmentForceComplete", e, "Cannot complete assignment");
} finally {
 try {
 if (con != null) {
 con.close();
 }
 } catch (SQLException e) {
 // Ignored
 }
}

