import java.sql.SQLException;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;

String modifiedBy = "#form.app_fd_inscription_ecole.modifiedBy#";
String dateModified = "#form.app_fd_inscription_ecole.date_action#";
String statut = "#form.app_fd_inscription_ecole.statut#";
String id = "#form.app_fd_inscription_ecole.id#";

DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
Connection con = null;
PreparedStatement stmtSelect = null;
PreparedStatement stmtInsert = null;
ResultSet rs = null;
String selectSQL = "SELECT c_historique FROM app_fd_inscription_ecole WHERE id = ?";
String updateSQL = "UPDATE app_fd_inscription_ecole SET c_historique = ? WHERE id = ?";

try {
    // Create a JSON object with statut, modifiedBy, and dateModified
    JSONObject newJsonObject = new JSONObject();
    newJsonObject.put("statut", statut);
    newJsonObject.put("modifiedBy", modifiedBy);
    newJsonObject.put("dateModified", dateModified);

    con = ds.getConnection();
    
    if (!con.isClosed()) {
        // First, retrieve the existing c_historique
        stmtSelect = con.prepareStatement(selectSQL);
        stmtSelect.setString(1, id);  // Set the id for the WHERE clause
        rs = stmtSelect.executeQuery();
        
        JSONArray jsonArray;
        
        if (rs.next()) {
            String existingHistorique = rs.getString("c_historique");
            
            // Check if c_historique exists and is not null or empty
            if (existingHistorique != null && !existingHistorique.isEmpty()) {
                // Parse the existing c_historique into a JSON array
                jsonArray = new JSONArray(existingHistorique);
            } else {
                // If no existing historique, initialize a new array
                jsonArray = new JSONArray();
            }
        } else {
            // If no record is found for the id, initialize a new array
            jsonArray = new JSONArray();
        }

        // Add the new JSON object to the array
        jsonArray.put(newJsonObject);

        // Prepare the update statement
        stmtInsert = con.prepareStatement(updateSQL);
        stmtInsert.setString(1, jsonArray.toString());  // Set the updated JSON array
        stmtInsert.setString(2, id);  // Set the id for the WHERE clause
        
        int rowsUpdated = stmtInsert.executeUpdate();
        
        if (rowsUpdated > 0) {
            LogUtil.info("DAO", "c_historique column updated successfully with appended JSON array for id: " + id);
        }
    }
} catch (SQLException e) {
    LogUtil.error("error update DAO", e, e.getMessage());
} finally {
    try {
        if (rs != null) {
            rs.close();
        }
        if (stmtSelect != null) {
            stmtSelect.close();
        }
        if (stmtInsert != null) {
            stmtInsert.close();
        }
        if (con != null) {
            con.close();
        }
    } catch (Exception ex) {
        LogUtil.error("DAO", ex, ex.getMessage());
    }
}
"}}]}

