 Connection con = null;
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 
public void processTableAndInsert(String newTabName, String oldTabName, String id, String id_master_column) {
 LogUtil.warn(" --------------------> CLONE DATA -----------> ", oldTabName);
 String newTableName = "jwdb.app_fd_" + newTabName;
 String oldTableName = "jwdb.app_fd_" + oldTabName;
 try {
 String describeSql = "DESCRIBE " + newTableName;
 PreparedStatement stmtDescribe = con.prepareStatement(describeSql);
 ResultSet rsDescribe = stmtDescribe.executeQuery();
 String Columns = "id";
 
 // Log to track column names
 LogUtil.info("Columns in new table: " + newTableName,"");

 while (rsDescribe.next()) {
 try {
 String columnName = rsDescribe.getString("Field");
 if (columnName.equals("id")) {
 continue;
 }
 Columns += "," + columnName;
 } catch (Exception e) {
 LogUtil.warn("----------->Cannot get column----------->", e.getMessage());
 }
 }
 stmtDescribe.close();

 String[] columnNames = Columns.split(",");
 String selectQuery = "SELECT * FROM " + oldTableName + " WHERE " + id_master_column + " = ?;";
 PreparedStatement stmtInsert = con.prepareStatement(selectQuery);
 stmtInsert.setString(1, id);
 ResultSet rs = stmtInsert.executeQuery();

 while (rs.next()) {
 String insertColumns = "";
 String valuePlaceholders = "";

 // Generate a new UUID for each new row
 UuidGenerator uuid = UuidGenerator.getInstance();
 String newId = uuid.getUuid(); // Generate new UUID

 insertColumns += "id,";
 valuePlaceholders += "'" + newId + "',"; // Insert the generated UUID

 for (String str : columnNames) {
 try {
 String columnName = str;
 String columnValue = rs.getString(columnName);

 // Skip the columns not required
 if (columnName.equals("id") || columnName.equals("c_historique") || columnName.equals("c_resultat")) {
 continue;
 }

 if (columnName.equals("c_annee_universitaire")) {
 valuePlaceholders += "'" + range + "',";
 } else if (columnName.equals("c_statut")) {
 valuePlaceholders += "'" + statut + "',";
 } else if (columnName.equals("createdBy")) {
 valuePlaceholders += "'" + username + "',";
 } else if (columnValue == null || columnValue.equals("")) {
 continue;
 } else {
 String originalString = String.valueOf(columnValue);
 String modifiedString = originalString.replace("'", "\\'").replace("\"", "\\\"");
 valuePlaceholders += "'" + modifiedString + "',";
 }

 insertColumns += columnName + ",";
 } catch (Exception e) {
 LogUtil.warn("----------->Cannot get column----------->", e.getMessage());
 }
 }

 // Remove the trailing commas
 insertColumns = insertColumns.substring(0, insertColumns.length() - 1);
 valuePlaceholders = valuePlaceholders.substring(0, valuePlaceholders.length() - 1);

 // Log the final insert query before execution
 LogUtil.info("-----------> insertQuery before execution: " + "INSERT INTO " + newTableName + " (" + insertColumns + ") VALUES (" + valuePlaceholders + ");","");

 String insertQuery = "INSERT INTO " + newTableName + " (" + insertColumns + ") VALUES (" + valuePlaceholders + ");";
 PreparedStatement insertStmt = con.prepareStatement(insertQuery);
 insertStmt.executeUpdate();
 insertStmt.close();
 }

 stmtInsert.close();
 } catch (Exception e) {
 LogUtil.warn("----------->Cannot clone data from ----------->", oldTableName);
 LogUtil.warn("Error executing update: ", e.getMessage());
 }
}

try {

 con = ds.getConnection();
 if (!con.isClosed()) {
 processTableAndInsert("inscription_ecole", "inscription_ecole", old_id, "id");
 }
} catch (Exception e) {
 LogUtil.error("DAO Error", e, "error get DAO");
} finally {
 try {
 if (con != null) {
 con.close();
 }
 } catch (SQLException e) {
 /* ignored */
 }
}"}},{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.Connection;
