{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"// Kill Processes and Update Existing Records
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;
import org.joget.workflow.model.service.WorkflowManager;

String currentuser = "#form.inscription_ecole.createdBy#";
String id_instance = "#form.inscription_ecole.id#";
String mailDirecteur = "#variable.nom_directeur#";

WorkflowManager workflowManager = (WorkflowManager) AppUtil.getApplicationContext().getBean("workflowManager");
Connection con = null;

try {
 LogUtil.info("assignmentForceComplete", "Starting process...");

 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();

 if (!con.isClosed()) {
 LogUtil.info("assignmentForceComplete", "Database connection opened.");

 String selectSQL = "SELECT DISTINCT e.id, shk.ActivityProcessDefName, shk.ActivityProcessId, shk.ActivityId, " +
 "e.c_formation, e.c_id_etablissement, e.modifiedBy, e.c_mail_directeur, e.c_statut " +
 "FROM jwdb.SHKAssignmentsTable AS shk " +
 "JOIN jwdb.app_fd_inscription_ecole AS e ON shk.ActivityProcessId = e.c_activityprocessid " +
 "WHERE e.createdBy = ? AND e.id != ?";

 PreparedStatement stmtSelectFolders = con.prepareStatement(selectSQL);
 stmtSelectFolders.setString(1, currentuser);
 stmtSelectFolders.setString(2, id_instance);

 LogUtil.info("assignmentForceComplete", "Executing select query to find records to update.");

 ResultSet rs = stmtSelectFolders.executeQuery();

 while (rs.next()) {
 LogUtil.info("assignmentForceComplete", "Found a record to update.");

 String activityProcessId = rs.getString("ActivityProcessId");
 String processDefId = rs.getString("ActivityProcessDefName");
 String activityId = rs.getString("ActivityId");
 String modifiedBy = rs.getString("modifiedBy");
 String recordId = rs.getString("id");
 String idEtablissement = rs.getString("c_id_etablissement");
 String formation = rs.getString("c_formation");
 String statut = rs.getString("c_statut");

 LogUtil.info("assignmentForceComplete", "Record details - activityProcessId: " + activityProcessId +
 ", processDefId: " + processDefId +
 ", activityId: " + activityId +
 ", recordId: " + recordId +
 ", statut: " + statut);

 // Step 1: Cancel old folder
 LogUtil.info("assignmentForceComplete", "Updating record to set c_steps='2' and c_statut='Annulé' for id: " + recordId);
 String updateField = "UPDATE app_fd_inscription_ecole SET c_steps = '2', c_statut = 'Annulé' WHERE id = ?";
 PreparedStatement updateStmt = con.prepareStatement(updateField);
 updateStmt.setString(1, recordId);
 int updateCount = updateStmt.executeUpdate();
 LogUtil.info("assignmentForceComplete", "Update statement executed. Rows affected: " + updateCount);

 // Step 2: Restore quota if needed
 if ("Accepté".equalsIgnoreCase(statut)) {
 LogUtil.info("assignmentForceComplete", "Restoring quota for formation: " + formation + ", etablissement: " + idEtablissement);
 String quotaUpdate = "UPDATE app_fd_quotas SET c_quota = c_quota + 1 WHERE id = CONCAT(?, ';', ?) AND c_quota_check = 'oui'";
 PreparedStatement quotaStmt = con.prepareStatement(quotaUpdate);
 quotaStmt.setString(1, formation);
 quotaStmt.setString(2, idEtablissement);
 int quotaUpdateCount = quotaStmt.executeUpdate();
 LogUtil.info("assignmentForceComplete", "Quota update executed. Rows affected: " + quotaUpdateCount);
 } else {
 LogUtil.info("assignmentForceComplete", "No quota restoration needed (statut != 'Accepté').");
 }

 // Step 3: Kill process
 String userToUse = currentuser.equals(modifiedBy) ? mailDirecteur : currentuser;

 LogUtil.info("assignmentForceComplete", "Determined user to complete the assignment: " + userToUse);

 if (userToUse != null && !userToUse.trim().isEmpty()) {
 LogUtil.info("assignmentForceComplete", "Sending 'Annuler' decision to activity: " + activityId);
 workflowManager.activityVariable(activityId, "decision", "Annuler");
 LogUtil.info("assignmentForceComplete", "Calling assignmentForceComplete for process: " + activityProcessId);
 workflowManager.assignmentForceComplete(processDefId, activityProcessId, activityId, userToUse);
 LogUtil.info("assignmentForceComplete", "Process killed for activity: " + activityId);
 } else {
 LogUtil.warn("assignmentForceComplete", "Skipped forceComplete due to null/empty user ID for process: " + activityProcessId);
 }
 }

 LogUtil.info("assignmentForceComplete", "Processing complete.");
 } else {
 LogUtil.warn("assignmentForceComplete", "Database connection is closed.");
 }
} catch (Exception e) {
 LogUtil.error("assignmentForceComplete", e, "Cannot complete assignment");
} finally {
 try {
 if (con != null) {
 con.close();
 LogUtil.info("assignmentForceComplete", "Database connection closed.");
 }
 } catch (SQLException e) {
 LogUtil.warn("assignmentForceComplete", "Error closing database connection: " + e.getMessage());
 }
}
