 } 



 }
} catch(Exception e) {
 LogUtil.error("assignmentForceComplete ", e, "Cannnot complete assignment");
} finally {
 try {
 if(con != null) {
 con.close();
 }
 } catch(SQLException e) {/* ignored */}
}









