Connection con = null;
DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
WorkflowManager workflowManager = (WorkflowManager) AppUtil.getApplicationContext().getBean("workflowManager");

String dir_mail = "#form.app_fd_insertion_resultat.createdBy#";

try {
 con = ds.getConnection();

 if (!con.isClosed()) {
 String query = "SELECT DISTINCT a.c_domaine,a.c_email_etudiant, c.c_duree_formation, b.id, b.c_etablissement, b.c_autre_diplome, a.id, a.createdBy, a.c_resultat, " +
 "b.c_nom, b.c_prenom, b.c_id_etudiant, a.c_annee_universitaire, a.c_cycle, a.c_domaine, a.c_specialite, " +
 "a.c_niveau, a.c_statut, a.c_mail_directeur " +
 "FROM app_fd_inscription_ecole a " +
 "JOIN app_fd_inscription_etud b ON a.c_id_etudiant = b.c_id_etudiant " +
 "JOIN app_fd_formations c ON c.id = a.c_formation " +
 "WHERE a.c_resultat IN ('Admis', 'Redoublant') " +
 "AND a.c_statut LIKE 'Cursus en progression' " +
 "AND a.c_id_etablissement = (SELECT c_id_etablissement " +
 " FROM app_fd_directeurs " +
 " WHERE c_adresse_electronique_directeur = ?)";

 PreparedStatement stmt1 = con.prepareStatement(query);
 stmt1.setString(1, dir_mail);

 ResultSet rs = stmt1.executeQuery();

 while (rs.next()) {
 UuidGenerator uuid = UuidGenerator.getInstance();

 String createdBy = rs.getString("createdBy");
 String c_email_etudiant = rs.getString("c_email_etudiant");
 String c_domaine = rs.getString("c_domaine");
 String resultat = rs.getString("c_resultat");
 String r_id = rs.getString("a.id");
 String c_etablissement = rs.getString("c_etablissement");
 String c_specialite = rs.getString("c_specialite");
 String c_annee_universitaire = rs.getString("c_annee_universitaire");
 String c_niveau = rs.getString("c_niveau");
 String c_cycle = rs.getString("c_cycle");
 String c_duree_formation = rs.getString("c_duree_formation");

 // Get user details
 DirectoryManager dm = (DirectoryManager) AppUtil.getApplicationContext().getBean("directoryManager");
 User user = dm.getUserByUsername(createdBy);

 // Assign user to a new department
 EmploymentDao dao = (EmploymentDao) AppUtil.getApplicationContext().getBean("employmentDao");
 String userId = user.getId();

 dao.unassignUserFromDepartment(userId, "etudiant_inscrit");
 dao.assignUserToDepartment(userId, "etudiants");

 if (!c_duree_formation.equals(c_niveau)) {
 // Dispatch workflow
 try {
 Map variables = new HashMap();
 if (resultat.equals("Admis")) {
 int new_nv = Integer.parseInt(c_niveau) + 1;
 variables.put("nv", String.valueOf(new_nv));
 } else {
 variables.put("nv", c_niveau);
 }
 variables.put("resultat", resultat);
 String recordId = uuid.getUuid();
 variables.put("username", createdBy);
 variables.put("old_id", r_id);
 variables.put("discipline", c_cycle);
 variables.put("domaine", c_domaine);
 variables.put("specs", c_specialite);
 variables.put("etabli", c_etablissement);
 String processDefId = "appcenter#latest#reinscrit";

 workflowManager.processStart(processDefId, null, variables, createdBy, recordId, false);
 } catch (Exception e) {
 LogUtil.error("Error dispatching workflow for user: " + createdBy, e, "Cannot dispatch file");
 }
 }

 // Final update
 String update_field = "UPDATE app_fd_inscription_ecole SET c_resultat = ?, c_statut = 'Année terminée' WHERE id = ?";
 PreparedStatement update_sql = con.prepareStatement(update_field);
 update_sql.setString(1, resultat);
 update_sql.setString(2, r_id);
 update_sql.executeUpdate();

 // Insert into app_fd_diplomes table
 String pId = uuid.getUuid();
 int yearInt = Integer.parseInt("#date.yyyy#");
 int debut = yearInt - (Integer.parseInt(c_duree_formation) - Integer.parseInt(c_niveau));
 int fin = yearInt + (Integer.parseInt(c_duree_formation) - Integer.parseInt(c_niveau));

 String insertSql = "INSERT INTO app_fd_diplomes " +
 "(id, c_specialite, c_annee_debut, c_annee_fin, c_diplome_obtenu, c_annee_universitaire, c_id_master, c_niveau, c_type_etablissement, c_resultat, c_nom_etablissement) " +
 "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
 PreparedStatement stmtInsert = con.prepareStatement(insertSql);
 stmtInsert.setString(1, pId);
 stmtInsert.setString(2, c_specialite);
 stmtInsert.setString(3, String.valueOf(debut));
 stmtInsert.setString(4, String.valueOf(fin));
 stmtInsert.setString(5, c_cycle);
 stmtInsert.setString(6, c_annee_universitaire);
 stmtInsert.setString(7, c_email_etudiant);
 stmtInsert.setString(8, c_niveau);
 stmtInsert.setString(9, "prive");
 stmtInsert.setString(10, resultat);
 stmtInsert.setString(11, c_etablissement);

 stmtInsert.executeUpdate();

 // Send email notification
 String mailSubject = "Résultats et réinscription";
 String mailContent = "Bonjour " + createdBy + ",\n\n"
 + "Nous vous informons que les résultats de votre dossier sont désormais disponibles. Veuillez les consulter dans votre espace personnel.\n\n"
 + "Afin de finaliser votre réinscription, merci de valider votre inscription.\n\n"
 + "Si vous avez des questions, n'hésitez pas à contacter notre support.\n\n"
 + "Cordialement,\n"
 + "L'équipe de réinscription";

 // Send email (adjust plugin handling as needed for your environment)
 Plugin plugin = pluginManager.getPlugin("org.joget.apps.app.lib.EmailTool");
 Map propertiesMap = AppPluginUtil.getDefaultProperties(plugin, null, appDef, null);
 propertiesMap.put("pluginManager", pluginManager);
 propertiesMap.put("appDef", appDef);
 propertiesMap.put("request", request);
 propertiesMap.put("toSpecific", c_email_etudiant); // Use the student email
 propertiesMap.put("subject", mailSubject);
 propertiesMap.put("message", mailContent);
 ((PropertyEditable) plugin).setProperties(propertiesMap);
 plugin.execute(propertiesMap);

 LogUtil.info("end", "-----------------");
 }
 }
} catch (Exception e) {
 LogUtil.error("Sample app - Form 1", e, "Error loading user data in load binder");
} finally {
 try {
 if (con != null) {
 con.close();
 }
 } catch (Exception ex) {
 LogUtil.error("Script P¨V commission", ex, "Error closing connection");
 }
}
